    'A QR code on the counter, receipt, or menu is the entire sign-up. No app to install, no card to carry.': 'Un código QR en el mostrador, recibo o menú completa todo el registro. Sin aplicación que instalar ni tarjeta que llevar.',
    'A single QR scan is the entire sign-up. No app download, no account setup — nothing stands between a passerby and becoming a member.': 'Un solo escaneo de QR completa todo el registro. Sin descargar una aplicación ni configurar una cuenta: nada se interpone entre un visitante y convertirse en miembro.',
