  'Apply: Credit model': 'Solicitar: modelo de crédito',
  'Choose a participation model and propose a reward rate. The final offer, limits, and settlement rules go into your agreement.': 'Elige un modelo de participación y propone una tasa de recompensa. La oferta final, los límites y las reglas de liquidación se incluyen en tu acuerdo.',
  'Choose the application that matches your proposed model.': 'Elige la solicitud que corresponda a tu modelo propuesto.',
  'Choose the model that fits your business.': 'Elige el modelo que se adapte a tu negocio.',
  'Cost to apply': 'Costo de solicitud',
  'Every verified transaction is an actual person spending with your business, not a click or a view.': 'Cada transacción verificada representa a una persona real comprando en tu negocio, no un clic ni una visualización.',
  'Get new customers while rewarding our members.': 'Consigue nuevos clientes mientras recompensas a nuestros miembros.',
  'Get started': 'Comenzar',
  'If you already use Synergize': 'Si ya usas Synergize',
