  'Local business owner welcoming rewards members': 'Propietario de un negocio local recibiendo a miembros de recompensas',
  'Members choose you for the reward': 'Los miembros te eligen por la recompensa',
  'Members only earn through participating businesses. An active offer puts your business in front of people deciding where to spend.': 'Los miembros solo obtienen recompensas en negocios participantes. Una oferta activa presenta tu negocio a personas que están decidiendo dónde gastar.',
  'Members see the active rate, availability, and restrictions before they visit or spend.': 'Los miembros ven la tasa activa, la disponibilidad y las restricciones antes de visitar o gastar.',
  'No charge': 'Sin cargo',
  'No online fee or rate is accepted here. Final commercial terms are confirmed in the signed agreement before activation.': 'Aquí no se acepta ninguna tarifa ni tasa en línea. Las condiciones comerciales finales se confirman en el acuerdo firmado antes de la activación.',
  'Participation models': 'Modelos de participación',
  'Publish a clear offer, reach members who are ready to spend, and pay only under the commercial model documented in your signed agreement.': 'Publica una oferta clara, llega a miembros listos para gastar y paga únicamente según el modelo comercial documentado en tu acuerdo firmado.',
  'Test the same offer, purchase-verification, and business-account workflows used by RewardMe with fictional businesses and sandbox data.': 'Prueba los mismos flujos de ofertas, verificación de compras y cuentas comerciales que usa RewardMe con negocios ficticios y datos de prueba.',
  'Open the test guide': 'Abrir la guía de prueba',
  'Questions? Email the program team': '¿Preguntas? Escribe al equipo del programa',
  'Real customers, not impressions': 'Clientes reales, no impresiones',
  'RewardMe pays the eligible member reward; commission and settlement follow the signed agreement.': 'RewardMe paga la recompensa elegible al miembro; la comisión y la liquidación siguen el acuerdo firmado.',
  '{program} pays the eligible member reward; commission and settlement follow the signed agreement.': '{program} paga la recompensa elegible al miembro; la comisión y la liquidación siguen el acuerdo firmado.',
  'Simple to operate': 'Fácil de operar',
  'Staff member scanning a member QR code at checkout': 'Empleado escaneando el código QR de un miembro en la caja',
  'Staff records each qualifying sale so the reward and business accounting both have an auditable entry.': 'El personal registra cada venta que cumple los requisitos para que la recompensa y la contabilidad del negocio tengan un registro auditable.',
  'Synergize is a separate private B2B credit network. Eligible Synergize business credit may support a RewardMe offer only when the applicable agreements permit it; RewardMe members do not need a Synergize account.': 'Synergize es una red privada de crédito B2B independiente. El crédito comercial elegible de Synergize solo puede respaldar una oferta de RewardMe cuando los acuerdos aplicables lo permitan; los miembros de RewardMe no necesitan una cuenta de Synergize.',
  'Terms before launch': 'Condiciones antes del lanzamiento',
  'Three steps. You pay for results, not access.': 'Tres pasos. Pagas por resultados, no por acceso.',
  'Verify purchases and settle clearly': 'Verifica compras y liquida con claridad',
  'You are paying for customer activity, not advertising space.': 'Pagas por actividad de clientes, no por espacio publicitario.',
  'Your business issues eligible credit; redemption, liability, and commission follow the signed agreement.': 'Tu negocio emite el crédito elegible; el canje, la responsabilidad y la comisión siguen el acuerdo firmado.',
  'Your reward rate, redemption access, settlement cycle, and restrictions are documented before an offer goes live.': 'Tu tasa de recompensa, acceso de canje, ciclo de liquidación y restricciones se documentan antes de publicar una oferta.',
  'Your staff verifies the member and purchase; the platform keeps the resulting customer and accounting record.': 'Tu personal verifica al miembro y la compra; la plataforma conserva el registro resultante del cliente y de contabilidad.',
