  'Get Started': 'Comenzar',
  'Helping local businesses grow while giving amazing Rewards to our members.':
    'Ayudamos a los negocios locales a crecer mientras damos excelentes recompensas a nuestros miembros.',
  'Business footer navigation': 'Navegación del pie de página para empresas',
