  'Partner With Us': 'Maging Katuwang Namin',
  'See how it works': 'Tingnan kung paano ito gumagana',
  'Partner benefits': 'Mga benepisyo ng katuwang',
  'No upfront cost': 'Walang paunang bayad',
  '15–25% commission': '15–25% komisyon',
  'Setup in days, not weeks': 'Pagsasaayos sa loob ng ilang araw, hindi linggo',
  'Local business owner ready to welcome {program} members':
    'May-ari ng lokal na negosyong handang tumanggap sa mga kasapi ng {program}',
  'Zero percent upfront cost': 'Walang porsiyentong paunang bayad',
  'UPFRONT COST': 'PAUNANG BAYAD',
  'WHY PARTNER WITH US': 'BAKIT DAPAT KAMING MAKATUWANG',
  'A steady stream of loyal, spending customers': 'Tuloy-tuloy na pagdating ng tapat at bumibiling mga kostumer',
  'Every member on the platform is already looking for places to earn — and businesses like yours are exactly where they want to spend.':
    'Naghahanap na ang bawat kasapi sa plataporma ng mga lugar kung saan kikita, at sa mga negosyong tulad ng sa iyo nila gustong gumastos.',
  'Bring in new, loyal customers': 'Magdala ng bago at tapat na mga kostumer',
  'Get discovered by members who are actively excited to earn Rewards — and who keep coming back to do it.':
    'Makilala ng mga kasaping sabik kumita ng mga gantimpala at patuloy na bumabalik upang gawin ito.',
  'Increase repeat visits': 'Dagdagan ang mga muling pagbisita',
  'Members return to keep earning, and bring friends and family along with them — compounding your customer base.':
    'Bumabalik ang mga kasapi upang patuloy na kumita at isinasama ang mga kaibigan at pamilya, kaya lumalaki ang iyong pangkat ng mga kostumer.',
  'Pay nothing to join. You only pay a 15%–25% commission, based on your industry, once a sale actually happens.':
    'Walang bayad sa pagsali. Magbabayad ka lamang ng 15%–25% komisyon, ayon sa iyong industriya, kapag may naganap na benta.',
  'Fast, easy onboarding': 'Mabilis at madaling pagsisimula',
  'We handle setup from end to end. Your staff just needs to scan a QR code when members make a purchase.':
    'Kami ang bahala sa buong pagsasaayos. Kailangan lamang i-scan ng iyong kawani ang QR code kapag may biniling kasapi.',
  'Limited partner space': 'Limitadong puwesto para sa katuwang',
  'Limited space': 'Limitadong puwesto',
  'There is a limit of businesses per type of business.':
    'May hangganan ang bilang ng mga negosyo sa bawat uri ng negosyo.',
  'Hotel partner welcoming a rewards member': 'Katuwang na otel na tumatanggap sa kasapi ng gantimpala',
  Hotels: 'Mga Otel',
