  'Staff member scanning a customer QR code at checkout':
    'Kawaning nag-i-scan ng QR code ng kostumer sa pagbabayad',
  '~10 sec': '~10 segundo',
  'to scan and log a sale at checkout': 'upang i-scan at itala ang benta sa pagbabayad',
  'GET STARTED TODAY': 'MAGSIMULA NGAYON',
  'Sign the agreement. We’ll take it from there.': 'Lagdaan ang kasunduan. Kami na ang bahala sa susunod.',
  'Sign the partnership agreement and a meeting will be scheduled for a short interview to see if your business will qualify.':
    'Lagdaan ang kasunduan ng pakikipagtuwang at magtatakda kami ng maikling panayam upang malaman kung kuwalipikado ang iyong negosyo.',
  'Open Business Demo': 'Buksan ang Pagpapakita para sa Negosyo',
  'Get Started Today': 'Magsimula Ngayon',
  'Have questions before you sign?': 'May mga tanong bago ka lumagda?',
  'Talk to our team and we’ll walk you through commission rates, onboarding, and what to expect.':
    'Kausapin ang aming pangkat at ipaliliwanag namin ang mga singil sa komisyon, pagsisimula, at mga dapat asahan.',
