  // Naka-sign in na kostumer: pangunahing pahina, QR, pamimili, mga kard na regalo, at kasapian.
  'A warm showcase for credits that feel personal, pretty, and quick to claim.':
    'Kaaya-ayang koleksiyon ng mga kreditong personal at madaling makuha.',
