  'Open agreements': 'Buksan ang mga kasunduan',
  'Membership enrollment': 'Pagpapatala sa kasapian',
  'The secure member request flow, staff review queue, activation, renewal, cancellation, recovery, and immutable audit history are implemented. Online payments remain out of scope.':
    'Naipatupad na ang ligtas na daloy ng kahilingan ng miyembro, pila ng pagsusuri ng kawani, pagsasaaktibo, pagpapanibago, pagkansela, pagbangon, at di-nababagong kasaysayan ng pagsusuri. Hindi pa saklaw ang mga bayad sa internet.',
  'RewardMe owner and operations': 'May-ari ng RewardMe at pangkat ng pagpapatakbo',
  'Approve final plan, identity-check, fee, renewal, cancellation, refund, and notification rules before public paid launch.':
    'Aprubahan ang huling mga tuntunin sa plano, pagpapatunay ng pagkakakilanlan, singil, pagpapanibago, pagkansela, pagsasauli ng bayad, at abiso bago ang bayad na pampublikong paglulunsad.',
